import{_ as t,o,c as s,ah as a}from"./chunks/framework.BMM80GXQ.js";const r="/assets/2.0/images/category/createField.png",i="/assets/2.0/images/category/general.png",n="/assets/2.0/images/category/label.png",l="/assets/2.0/images/category/validation.png",g="/assets/2.0/images/category/configuration.png",p="/assets/2.0/images/category/setting.png",c="/assets/2.0/images/category/fielddataGrid.png",d="/assets/2.0/images/category/output.png",C=JSON.parse('{"title":"Category Fields","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/categoryField/category-fields.md","filePath":"2.0/categoryField/category-fields.md","lastUpdated":1775051911000}'),f={name:"2.0/categoryField/category-fields.md"};function u(m,e,h,y,_,b){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="category-fields" tabindex="-1">Category Fields <a class="header-anchor" href="#category-fields" aria-label="Permalink to &quot;Category Fields&quot;">​</a></h1><p>Category Fields are similar to attributes for products, whereas category fields are used in categories.</p><p>Category fields generally refer to specific attributes or types of information used to classify or organize items.</p><h3 id="steps-to-create-a-category-fields-in-unopim" tabindex="-1">Steps to Create a Category Fields in UnoPim <a class="header-anchor" href="#steps-to-create-a-category-fields-in-unopim" aria-label="Permalink to &quot;Steps to Create a Category Fields in UnoPim&quot;">​</a></h3><ol><li><p>Click on <strong>Catalog &gt;&gt; Category Field &gt;&gt; Click Category Field</strong> button as shown in the below image.</p><p><img src="'+r+'" alt="Category Field"></p></li><li><p>Now enter the <strong>Code</strong> and <strong>Type</strong> inside the general section.</p></li></ol><h3 id="in-unopim-by-default-there-are-10-types" tabindex="-1">In UnoPim by default there are 10 Types <a class="header-anchor" href="#in-unopim-by-default-there-are-10-types" aria-label="Permalink to &quot;In UnoPim by default there are 10 Types&quot;">​</a></h3><p><strong>1) Text</strong> - A field that allows the user to enter a single line of text. It is typically used for short inputs like names, email addresses, or search queries.</p><p><strong>2) Textarea</strong> - A field that provides a larger area for users to input multi-line text. It’s useful for longer responses or comments, such as descriptions or messages.</p><p><strong>3) Boolean</strong> - Represents a true or false value. It&#39;s often used in forms to capture yes/no or on/off selections.</p><p><strong>4) Select</strong> - A dropdown menu that allows users to choose one option from a list. It’s useful for making selections where only one option should be chosen from a predefined set of options.</p><p><strong>5) Multiselect</strong> - Similar to a select field but allows users to choose multiple options from a list. It’s useful when multiple selections are valid and necessary.</p><p><strong>6) Datetime</strong> - A field that allows users to select a specific date and time. It’s often used for scheduling or timestamping events.</p><p><strong>7) Date</strong> - A field that allows users to select or input a date only (without time). It’s used for choosing a specific day in forms and calendars.</p><p><strong>8) Image</strong> - A field for uploading or displaying images. Users can either upload an image file or view an image that’s already been uploaded.</p><p><strong>9) File</strong> - A field that allows users to upload files. It can accept various file types, such as documents, images, or other file formats.</p><p><strong>10) Checkbox</strong> - A small box that can be checked or unchecked. It’s used for binary choices, where a user can select or deselect an option, often used for agreements or preferences.</p><p><strong>Note -</strong> The <strong>Is Unique</strong> Validation is only available for Type - <strong>Text, Datetime &amp; Date</strong></p><p><img src="'+i+'" alt="General"></p><ol start="3"><li><p>Enter the Label of your category field as shown in the below image.</p><p><img src="'+n+'" alt="Label"></p></li><li><p>Select the Validation if you want to make your category field as a required field.</p><p><img src="'+l+'" alt="Validation"></p></li><li><p>Select the field if you want to make the category field value as per the locale.</p></li></ol><p>This allows you to manage the category field for different locale in the category.</p><p><img src="'+g+'" alt="Configuration"></p><ol start="6"><li><p>Now in the settings option enable the <strong>status</strong> of the field enter the <strong>position</strong> of your field at where you want to place this field as a sort order while creating a category and then select the display section as a general section or configurable section.</p><p><img src="'+p+'" alt="Settings"></p></li></ol><p>At Last click on <strong>Save Category Field</strong> button and the new category field is created successfully as shown in the image below.</p><p><img src="'+c+'" alt="Datagrid"></p><p>Now go to <strong>Catalog &gt;&gt; Categories &gt;&gt; Create Category</strong> and you are able to see the <strong>New Category Field</strong> while creating or updating category.</p><p><img src="'+d+'" alt="Output"></p>',26)])])}const F=t(f,[["render",u]]);export{C as __pageData,F as default};
